/**
 * @file mcuno60_patches.c
 * Factory patch data for MCUno-60 Synthesizer
 */

#include "mcuno60_patches.h"
#include <stddef.h>


/* Factory bank names ("Juno-60 A1", "Juno-60 A2", ... "Juno-106 B2") are not
 * exposed: the browser shows the merged bank names in VIEW_BANK_NAMES below.
 * Factory bank identity is still implied by index order, which the remap relies
 * on -- each view bank consumes factory banks (2n-1) and (2n). */
_Static_assert(MCUNO60_FACTORY_BANKS == (MCUNO60_NUM_BANKS - 1) * 2,
               "view bank count must match the 2:1 factory bank remap");
_Static_assert(MCUNO60_FACTORY_BANKS * MCUNO60_FACTORY_PATCHES_PER_BANK
                   == (MCUNO60_NUM_BANKS - 1) * MCUNO60_PATCHES_PER_BANK,
               "merged bank patch count must match the total factory patch count");

