/* ---------------------------------------------------------------------------
 * User-visible patch bank layout
 *
 * The factory data above is a plain 8 x 32 grid generated from
 * factory_patches.ts. The patch browser presents a different 5-bank view:
 *
 *   bank 0  Benchmarking   4 patches (not a factory bank)
 *   bank 1  Juno-60 A     64 patches (factory banks 0 + 1)
 *   bank 2  Juno-60 B     64 patches (factory banks 2 + 3)
 *   bank 3  Juno-106 A    64 patches (factory banks 4 + 5)
 *   bank 4  Juno-106 B    64 patches (factory banks 6 + 7)
 *
 * Banks 1..4 are straight concatenations of two factory banks, so their
 * lookup is an arithmetic remap with no extra table. Only bank 0 needs
 * an explicit patch list, which is why it is stored as descriptors.
 * ------------------------------------------------------------------------- */

static const char *VIEW_BANK_NAMES[MCUNO60_NUM_BANKS] = {
    "Benchmarking",
    "Juno-60 A",
    "Juno-60 B",
    "Juno-106 A",
    "Juno-106 B",
};

/* Factory coordinates of the three factory-derived benchmark patches:
 *   [0] A15 Moving Strings (numerical/timbre comparison)
 *   [1] A57 Thud Wah       (general listening reference)
 *   [2] B76 Martian Chord  (VCF self-oscillation / low-cutoff isolation)
 *
 * Benchmark patch [3] is the synthetic CPU worst case built below. */
typedef struct {
    uint8_t factory_bank;
    uint8_t factory_patch;
} FactoryRef;

static const FactoryRef BENCH_FACTORY_REFS[MCUNO60_BENCH_PATCHES - 1] = {
    { 4, 4 },  /* A15 Moving Strings */
    { 5, 6 },  /* A57 Thud Wah       */
    { 3, 21 }, /* B76 Martian Chord  */
};

/* Synthetic CPU worst case: every oscillator and modulation source active,
 * max resonance, both chorus BBD units. Not a factory patch -- see
 * docs/OPTIMISATIONS.md section 11. */
static const JunoEngineParams BENCH_HEAVY_PARAMS = {
    .lfo_rate = 21.1052f,
    .lfo_delay = 0.0f,

    .dco_lfo_mod = 1.0f,
    .dco_pwm = 1.0f,
    .dco_pwm_mode = 1,          /* LFO */
    .dco_saw = true,
    .dco_pulse = true,
    .dco_sub = true,
    .dco_sub_octave = -1,       /* f0/2 */
    .dco_sub_level = 1.0f,
    .dco_noise = 1.0f,

    .hpf_position = 3,

    .vcf_cutoff = 0.53f,
    .vcf_res = 1.0f,
    .vcf_env_mod = 1.0f,
    .vcf_env_polarity = 1,
    .vcf_lfo_mod = 1.0f,
    .vcf_kbd_track = 1.0f,

    .vca_mode = 0,             /* ENV */
    .vca_level = 1.0f,

    .env_attack = 0.46f,
    .env_decay = 0.46f,
    .env_sustain = 0.46f,
    .env_release = 0.46f,

    .chorus_mode = 3,          /* I+II, both BBD units */

    .master_volume = 0.8f,
    .master_tune = 0.1f,
    .bender = 0.1f,
    .mod_wheel = 0.1f,
    .poly_mode = 0,            /* POLY1 */
    .hold = false,

    .arp_on = false,
    .arp_rate = 6.0f,
    .arp_range = 1,
    .arp_mode = 0,             /* UP */

    .model = 0,               /* Juno-60 */
};

static const char *BENCH_HEAVY_NAME = "Bench Heavy (CPU)";

uint8_t mcuno60_get_bank_patch_count(uint8_t bank_idx)
{
    if (bank_idx >= MCUNO60_NUM_BANKS) {
        return 0;
    }
    if (bank_idx == MCUNO60_BENCH_BANK) {
        return MCUNO60_BENCH_PATCHES;
    }
    return MCUNO60_PATCHES_PER_BANK;
}

const char *mcuno60_get_bank_name(uint8_t bank_idx)
{
    if (bank_idx >= MCUNO60_NUM_BANKS) {
        return "Unknown";
    }
    return VIEW_BANK_NAMES[bank_idx];
}

const char *mcuno60_get_patch_name(uint8_t bank_idx, uint8_t patch_idx)
{
    if (patch_idx >= mcuno60_get_bank_patch_count(bank_idx)) {
        return "Unknown";
    }
    if (bank_idx == MCUNO60_BENCH_BANK) {
        if (patch_idx == MCUNO60_BENCH_PATCHES - 1) {
            return BENCH_HEAVY_NAME;
        }
        return MCUNO60_PATCH_NAMES[BENCH_FACTORY_REFS[patch_idx].factory_bank]
                                  [BENCH_FACTORY_REFS[patch_idx].factory_patch];
    }
    /* View bank N is factory banks (2N-2) and (2N-1), the first holding the
     * lower 32 patch indices. */
    if (patch_idx < MCUNO60_FACTORY_PATCHES_PER_BANK) {
        return MCUNO60_PATCH_NAMES[bank_idx * 2 - 2][patch_idx];
    }
    return MCUNO60_PATCH_NAMES[bank_idx * 2 - 1][patch_idx - MCUNO60_FACTORY_PATCHES_PER_BANK];
}

const JunoEngineParams *mcuno60_get_patch_params(uint8_t bank_idx, uint8_t patch_idx)
{
    if (patch_idx >= mcuno60_get_bank_patch_count(bank_idx)) {
        return NULL;
    }
    if (bank_idx == MCUNO60_BENCH_BANK) {
        if (patch_idx == MCUNO60_BENCH_PATCHES - 1) {
            return &BENCH_HEAVY_PARAMS;
        }
        return &MCUNO60_PATCH_PARAMS[BENCH_FACTORY_REFS[patch_idx].factory_bank]
                                       [BENCH_FACTORY_REFS[patch_idx].factory_patch];
    }
    /* Mirror of the index arithmetic in mcuno60_get_patch_name(). */
    if (patch_idx < MCUNO60_FACTORY_PATCHES_PER_BANK) {
        return &MCUNO60_PATCH_PARAMS[bank_idx * 2 - 2][patch_idx];
    }
    return &MCUNO60_PATCH_PARAMS[bank_idx * 2 - 1][patch_idx - MCUNO60_FACTORY_PATCHES_PER_BANK];
}
